/**
 * Item
 */
export const zItem = z.object({
    opportunity_id: z.string(),
    sales_agent: z.string(),
    product: z.string().nullable(),
    account: z.string().nullable(),
    sales_price: z.int().nullable(),
    value_band: z.enum([
        'alto',
        'médio',
        'baixo'
    ]).nullable(),
    engage_date: z.iso.date().nullable(),
    age_days: z.int().nullable(),
    group: z.enum([
        'focar',
        'qualificar',
        'acompanhar',
        'revisar',
        'nao_pontuavel'
    ]),
    deal_stage: z.enum(['Engaging', 'Prospecting']),
    missing_field: z.enum([
        'product',
        'sales_price',
        'engage_date'
    ]).nullable(),
    tie_size: z.int(),
    reasons: z.array(z.union([
        z.object({
            code: z.literal('age_within_won_cycle')
        }).and(zAgeWithinWonCycle),
        z.object({
            code: z.literal('age_above_won_cycle')
        }).and(zAgeAboveWonCycle),
        z.object({
            code: z.literal('age_above_cycle_limit')
        }).and(zAgeAboveCycleLimit),
        z.object({
            code: z.literal('prospecting_stage')
        }).and(zProspectingStage),
        z.object({
            code: z.literal('missing_field')
        }).and(zMissingFieldReason),
        z.object({
            code: z.literal('list_price')
        }).and(zListPrice),
        z.object({
            code: z.literal('no_product')
        }).and(zNoProduct),
        z.object({
            code: z.literal('no_list_price')
        }).and(zNoListPrice)
    ])),
    next_action: z.union([
        z.object({
            code: z.union([
                z.literal('check_prospecting'),
                z.literal('fix_missing_fields')
            ])
        }).and(zSimpleAction),
        z.object({
            code: z.union([
                z.literal('check_progress'),
                z.literal('check_status'),
                z.literal('confirm_still_active')
            ])
        }).and(zAccountAction),
        z.object({
            code: z.literal('fix_missing_field')
        }).and(zFixFieldAction)
    ])
});

